interface PropsArgs {
    labelID?: string;
    elementID?: string;
    page?: number;
    sort?: Sort;
    filter?: Filter;
    search?: SearchParameters;
    mailSettings?: MailSettings;
}

export interface SetupArgs extends PropsArgs {
    messages?: Element[];
    conversations?: Element[];
    inputLabelID?: string;
    page?: number;
    totalMessages?: number;
    totalConversations?: number;
    mockMessages?: boolean;
    mockConversations?: boolean;
    Component?: typeof MailboxContainer;
    mailSettings?: MailSettings;
}

export const props = {
    labelID: 'labelID',
    userSettings: {} as UserSettings,
    breakpoints: { isDesktop: true } as Breakpoints,
    elementID: undefined,
    onCompose: jest.fn(),
    isComposerOpened: false,
};

const defaultSort = { sort: 'Time', desc: true } as Sort;
const defaultFilter = {};
const defaultSearch = {};
const defaultMailSettings = { ViewMode: VIEW_MODE.GROUP, Shortcuts: 1 } as MailSettings;

export const labels: Label[] = [
    { ID: 'labelID', Type: LABEL_TYPE.MESSAGE_LABEL, Name: 'label' },
    { ID: 'label1', Type: LABEL_TYPE.MESSAGE_LABEL, Name: 'label1' },
    { ID: 'label2', Type: LABEL_TYPE.MESSAGE_LABEL, Name: 'label2' },
    { ID: 'label3', Type: LABEL_TYPE.MESSAGE_LABEL, Name: 'label3' },
    { ID: 'label4', Type: LABEL_TYPE.MESSAGE_LABEL, Name: 'label4' },
] as Label[];

export const folders: Folder[] = [
    { ID: 'folder1', Type: LABEL_TYPE.MESSAGE_FOLDER, Name: 'folder1' },
    { ID: 'folder2', Type: LABEL_TYPE.MESSAGE_FOLDER, Name: 'folder2' },
    { ID: 'folder3', Type: LABEL_TYPE.MESSAGE_FOLDER, Name: 'folder3' },
    { ID: 'folder4', Type: LABEL_TYPE.MESSAGE_FOLDER, Name: 'folder4' },
] as Folder[];

export const getElements = (count: number, label = props.labelID, elementProps: any = {}): Element[] =>
    range(0, count).map((i) => ({
        ID: `id${i}`,
        Labels: [{ ID: label, ContextTime: i }] as ConversationLabel[],
        LabelIDs: [label],
        ...elementProps,
    }));

export const getProps = ({
    labelID = props.labelID,
    elementID,
    page = 0,
    sort = defaultSort,
    filter = defaultFilter,
    search = defaultSearch,
    mailSettings = defaultMailSettings,
}: PropsArgs) => {
    const urlSearchParams = new URLSearchParams();
    if (page !== 0) {
        urlSearchParams.set('page', String(page + 1));
    }
    if (sort !== defaultSort) {
        urlSearchParams.set('sort', sortToString(sort) || '');
    }
    if (filter !== defaultFilter) {
        urlSearchParams.set('filter', filterToString(filter) || '');
    }
    if (search !== defaultSearch) {
        urlSearchParams.set('keyword', keywordToString(search.keyword || '') || '');
    }

    getHistory().push(`#${urlSearchParams.toString()}`);

    return { ...props, labelID, elementID, mailSettings };
};

export const baseApiMocks = () => {
    addApiMock('importer/v1/importers', () => ({ Importers: [] }));
    addApiMock('settings/calendar', () => ({}));
    addApiMock('calendar/v1', () => ({}));
    addApiMock('payments/plans', () => ({}));
};

export const setup = async ({
    messages = [],
    conversations = [],
    totalMessages = messages.length,
    totalConversations = conversations.length,
    mockMessages = true,
    mockConversations = true,
    Component = MailboxContainer,
    ...propsArgs
}: SetupArgs = {}) => {
    minimalCache();
    baseApiMocks();
    const props = getProps(propsArgs);

    addToCache('Labels', [{ ID: props.labelID }]);
    if (mockMessages) {
        addApiMock('mail/v4/messages', () => ({ Total: totalMessages, Messages: messages }));
    }
    if (mockConversations) {
        addApiMock('mail/v4/conversations', () => ({ Total: totalConversations, Conversations: conversations }));
    }

    addToCache('Labels', [...labels, ...folders]);
    addToCache('MessageCounts', [{ LabelID: props.labelID, Total: totalMessages, Unread: totalMessages }]);
    addToCache('ConversationCounts', [
        { LabelID: props.labelID, Total: totalConversations, Unread: totalConversations },
    ]);
    addToCache('MailSettings', props.mailSettings);

    const result = await render(<Component {...props} />, false);
    const rerender = (propsArgs: PropsArgs) => result.rerender(<Component {...getProps(propsArgs)} />);
    const getItems = () => result.getAllByTestId('message-item', { exact: false });

    return { ...result, rerender, getItems };
};

export const sendEvent = async (event: Event) => {
    await act(async () => {
        triggerEvent(event);
        await wait(0);
    });
};

export const expectElements = (getItems: () => HTMLElement[], total: number, isPlaceholder: boolean) => {
    const items = getItems();
    expect(items.length).toBe(total);
    items.forEach((item) => {
        if (isPlaceholder) {
            expect(item.getAttribute('data-element-id')).toContain('placeholder');
        } else {
            expect(item.getAttribute('data-element-id')).not.toContain('placeholder');
        }
    });
};

import { configureStore } from '@reduxjs/toolkit';
import elements from './elements/elementsSlice';
import attachments from './attachments/attachmentsSlice';
import conversations from './conversations/conversationsSlice';
import messages from './messages/messagesSlice';
import contacts from './contacts/contactsSlice';

export const store = configureStore({
    reducer: {
        elements,
        conversations,
        attachments,
        messages,
        contacts,
    },
    middleware: (getDefaultMiddleware) =>
        getDefaultMiddleware({
            // Serialization checks have to be restored
            // But we need some kind of regex ignore capacities
            serializableCheck: {
                // Ignore these field paths in state
                // ignoredPaths: [],

                // TODO
                ignoreState: true,

                // Ignore these field paths in all actions
                ignoredActionPaths: [
                    'meta.arg',
                    'payload.abortController',
                    'payload.preparation',
                    'payload.decryption',
                    'payload',
                    'payload.attachment',

                    'payload.contacts',
                    'payload.contactGroups',
                ],

                warnAfter: 100,
            },
        }),
});

// Infer the `RootState` and `AppDispatch` types from the store itself
export type RootState = ReturnType<typeof store.getState>;

// Inferred type: {posts: PostsState, comments: CommentsState, users: UsersState}
export type AppDispatch = typeof store.dispatch;

import { configureStore } from '@reduxjs/toolkit';
import { Api } from '@proton/shared/lib/interfaces';
import elementsReducer, { newState } from './elementsSlice';
import { backendActionFinished, backendActionStarted, load } from './elementsActions';
import * as elementQuery from './helpers/elementQuery';

describe('elements list request state', () => {
    afterEach(() => {
        jest.useRealTimers();
        jest.restoreAllMocks();
    });

    const createStore = () =>
        configureStore({
            reducer: { elements: elementsReducer },
            middleware: (getDefaultMiddleware) => getDefaultMiddleware({ serializableCheck: false }),
        });
    const queryParams = () => ({
        api: jest.fn() as unknown as Api,
        abortController: undefined,
        conversationMode: true,
        page: 0,
        params: newState().params,
    });

    it('tracks overlapping backend actions', () => {
        const store = createStore();
        store.dispatch(backendActionStarted());
        store.dispatch(backendActionStarted());
        expect(store.getState().elements.pendingActions).toBe(2);
        store.dispatch(backendActionFinished());
        expect(store.getState().elements.pendingActions).toBe(1);
        store.dispatch(backendActionFinished());
        expect(store.getState().elements.pendingActions).toBe(0);
    });

    it('rejects stale data and retries after one second without committing it', async () => {
        jest.useFakeTimers();
        const store = createStore();
        jest.spyOn(elementQuery, 'queryElements').mockResolvedValue({
            abortController: new AbortController(),
            Total: 1,
            Elements: [{ ID: 'stale' }],
            Stale: 1,
        });

        const result = await store.dispatch(load(queryParams()));
        expect(load.rejected.match(result)).toBe(true);
        expect(store.getState().elements.pages).toEqual([]);
        expect(store.getState().elements.elements).toEqual({});

        jest.advanceTimersByTime(1000);
        expect(store.getState().elements.pendingRequest).toBe(false);
        expect(store.getState().elements.retry).toMatchObject({ count: 1, error: undefined });
    });

    it('retries failed requests after two seconds', async () => {
        jest.useFakeTimers();
        const store = createStore();
        const error = new Error('fetch failed');
        jest.spyOn(elementQuery, 'queryElements').mockRejectedValue(error);

        const result = await store.dispatch(load(queryParams()));
        expect(load.rejected.match(result)).toBe(true);
        jest.advanceTimersByTime(1999);
        expect(store.getState().elements.pendingRequest).toBe(true);
        jest.advanceTimersByTime(1);
        expect(store.getState().elements.pendingRequest).toBe(false);
        expect(store.getState().elements.retry).toMatchObject({ count: 1, error });
    });
});

